import threading
from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least recently used entry.

    Safe for concurrent use: every operation that touches the ordering or the
    counters holds the lock, so a reader's move_to_end cannot interleave with
    another thread's eviction.
    """

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._lock = threading.Lock()

    def get(self, key, default=None):
        with self._lock:
            if key not in self._data:
                self._misses += 1
                return default
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key]

    def put(self, key, value):
        with self._lock:
            if key in self._data:
                self._data.move_to_end(key)
            self._data[key] = value
            if len(self._data) > self.capacity:
                self._data.popitem(last=False)

    def stats(self):
        with self._lock:
            return {
                "hits": self._hits,
                "misses": self._misses,
                "size": len(self._data),
            }

    def pop(self, key, default=None):
        with self._lock:
            return self._data.pop(key, default)

    def clear(self):
        with self._lock:
            self._data.clear()
            self._hits = 0
            self._misses = 0

    def __contains__(self, key):
        with self._lock:
            return key in self._data

    def __len__(self):
        with self._lock:
            return len(self._data)

    def __iter__(self):
        # Snapshot under the lock: iterating the live OrderedDict would raise if
        # another thread inserted or evicted mid-iteration. Oldest first.
        with self._lock:
            return iter(list(self._data))

    def __repr__(self):
        with self._lock:
            return f"LRUCache(capacity={self.capacity}, size={len(self._data)})"
